import pytest


def age_at(born: int, now: int) -> int:
    """Whole years between birth year `born` and the current year `now`.

    The current year is supplied by the caller; the clock is never read.
    Only years are compared, so the result is `now - born`.

    Raises ValueError if `now` is earlier than `born`.
    """
    if now < born:
        raise ValueError(f"now ({now}) is earlier than born ({born})")
    return now - born


def test_age_at_typical() -> None:
    assert age_at(1990, 2024) == 34
    assert age_at(2000, 2001) == 1


def test_age_at_same_year_is_zero() -> None:
    assert age_at(2024, 2024) == 0


def test_age_at_across_century() -> None:
    assert age_at(1899, 2001) == 102


def test_age_at_small_and_negative_years() -> None:
    assert age_at(-10, 10) == 20
    assert age_at(0, 0) == 0


def test_age_at_now_before_born_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2025, 2024)


def test_age_at_is_pure() -> None:
    assert age_at(1980, 2020) == age_at(1980, 2020) == 40
